# -*- coding: utf-8 -*-
"""Build reproducible single-package ZIPs. Generated bytes stay in dist/."""
from __future__ import annotations

import hashlib
import json
import sys
import zipfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from skill_lib import ROOT, package_digest

FIXED = (1980, 1, 1, 0, 0, 0)


def iter_files(package: Path) -> list[Path]:
    return sorted(
        [path for path in package.rglob("*") if path.is_file()],
        key=lambda path: path.relative_to(package).as_posix().encode("utf-8"),
    )


def build_one(package: Path, dest: Path) -> dict:
    files = {}
    dest.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(dest, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for path in iter_files(package):
            rel = path.relative_to(package).as_posix()
            data = path.read_bytes()
            files[rel] = data
            info = zipfile.ZipInfo(filename=f"{package.name}/{rel}", date_time=FIXED)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o644 << 16
            archive.writestr(info, data)
    blob = dest.read_bytes()
    return {
        "name": package.name,
        "file": dest.name,
        "size": len(blob),
        "sha256": hashlib.sha256(blob).hexdigest(),
        "packageDigest": package_digest(files),
    }


def approved_packages() -> list[Path]:
    catalog = json.loads((ROOT / "catalog" / "packages.json").read_text(encoding="utf-8"))
    found = []
    for item in catalog["packages"]:
        if item.get("distribution") != "source-approved":
            continue
        found.append(ROOT / item["path"])
    return found


def main(argv: list[str]) -> int:
    output = ROOT / "dist"
    if "--output" in argv:
        output = Path(argv[argv.index("--output") + 1])
        if not output.is_absolute():
            output = ROOT / output
    rows = []
    for package in approved_packages():
        if not (package / "SKILL.md").is_file():
            print("missing", package, file=sys.stderr)
            return 1
        version = "unversioned"
        text = (package / "SKILL.md").read_text(encoding="utf-8")
        for line in text.splitlines():
            if line.strip().startswith("version:"):
                version = line.split(":", 1)[1].strip().strip('"')
        rows.append(build_one(package, output / f"{package.name}-{version}.zip"))
    listing = output / "catalog.json"
    sums = output / "SHA256SUMS"
    output.mkdir(parents=True, exist_ok=True)
    listing.write_text(json.dumps({"assets": rows}, indent=2) + "\n", encoding="utf-8")
    sums.write_text("".join(f"{row['sha256']}  {row['file']}\n" for row in rows), encoding="utf-8")
    if "--check" in argv:
        side = output / "_check"
        if side.exists():
            import shutil

            shutil.rmtree(side)
        second = []
        catalog = json.loads((ROOT / "catalog" / "packages.json").read_text(encoding="utf-8"))
        for item in catalog["packages"]:
            if item.get("distribution") != "source-approved":
                continue
            package = ROOT / item["path"]
            text = (package / "SKILL.md").read_text(encoding="utf-8")
            version = "unversioned"
            for line in text.splitlines():
                if line.strip().startswith("version:"):
                    version = line.split(":", 1)[1].strip().strip('"')
            second.append(build_one(package, side / f"{package.name}-{version}.zip"))
        if [row["sha256"] for row in rows] != [row["sha256"] for row in second]:
            print("ZIP not reproducible", file=sys.stderr)
            return 1
    print(f"built {len(rows)} packages")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
